    def xǁQuantumRelevanceScorerǁ_cosine_similarity__mutmut_orig(
        self,
        vec1: list[float] | Any,
        vec2: list[float] | Any,
    ) -> float:
        """Calculate cosine similarity between two vectors.

        Args:
            vec1: First vector
            vec2: Second vector

        Returns:
            Cosine similarity score (0-1)
        """
        if vec1 is None or vec2 is None:
            return 0.0

        if not vec1 or not vec2:
            return 0.0

        # Convert to lists if numpy arrays
        if NUMPY_AVAILABLE and np is not None:
            if isinstance(vec1, np.ndarray):
                vec1 = vec1.tolist()
            if isinstance(vec2, np.ndarray):
                vec2 = vec2.tolist()

        # Ensure same length
        if len(vec1) != len(vec2):
            logger.warning(
                "Vector length mismatch: %d vs %d, returning 0.0", len(vec1), len(vec2)
            )
            return 0.0

        # Calculate dot product and norms
        dot_product = sum(a * b for a, b in zip(vec1, vec2))
        norm1 = math.sqrt(sum(a * a for a in vec1))
        norm2 = math.sqrt(sum(b * b for b in vec2))

        if norm1 == 0 or norm2 == 0:
            return 0.0

        similarity = dot_product / (norm1 * norm2)

        # Clamp to [0, 1] range (cosine similarity can be negative)
        return max(0.0, min(1.0, similarity))

